/// `tests/bugs/modalg_6/bug28776`
/// kentron: sub-shapes named by OCCT's enumeration are selected by position (draw_selectors.json)
#[test]
fn bug28776() -> DrawResult<()> {
    let mut d = Draw::new();
    d.r#box(&["b1", "10", "10", "10"])?;
    d.r#box(&["b2", "10", "10", "10"])?;
    d.r#box(&["b3", "10", "10", "10"])?;
    d.bclearobjects(&[])?;
    d.bcleartools(&[])?;
    d.baddobjects(&["b1", "b2", "b3"])?;
    d.bfillds(&[])?;
    d.bbuild(&["r"])?;
    d.explode(&["r", "v"])?;
    d.nearest(&["r_1", "r", "V", "0.0", "0.0", "0.0", "0.0"])?;
    d.boporigin(&["r_1"])?;
    d.checknbshapes(&["r_1_or", "-vertex", "3"])?;
    d.explode(&["r", "e"])?;
    d.nearest(&["r_1", "r", "E", "0.0", "0.0", "5.0", "10.0"])?;
    d.boporigin(&["r_1"])?;
    d.checknbshapes(&["r_1_or", "-edge", "3"])?;
    d.explode(&["r", "f"])?;
    d.nearest(&["r_1", "r", "F", "0.0", "5.0", "5.0", "100.0"])?;
    d.boporigin(&["r_1"])?;
    d.checknbshapes(&["r_1_or", "-face", "3"])?;
    d.explode(&["r", "so"])?;
    d.nearest(&["r_1", "r", "SO", "5.0", "5.0", "5.0", "1000.0"])?;
    d.boporigin(&["r_1"])?;
    d.checknbshapes(&["r_1_or", "-solid", "3"])?;
    Ok(())
}

